import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    # sex label variant and normalisation
    if 'sex' in df.columns:
        df['sex'] = df['sex'].where(df['sex'].isna(), df['sex'].astype(str).str.strip().str.lower())
    # flipper_length_mm: ensure numeric and fix sign errors
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
        df['flipper_length_mm'] = df['flipper_length_mm'].abs()
    # body_mass_g: ensure numeric
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    return df

def answer(df):
    dfc = clean(df)
    means = dfc.groupby('species', dropna=True)['flipper_length_mm'].mean()
    return {str(k): float(v) for k, v in means.items()}
